const MAX_PAGE_SIZE = 1000;

export function parsePagination(
  query: { page?: string | (string | null)[]; size?: string | (string | null)[] },
  defaults: { page?: number; size?: number } = {}
): { page: number; size: number } {
  const defaultPage = defaults.page ?? 1;
  const defaultSize = defaults.size ?? 10;

  const rawPage = Number(Array.isArray(query.page) ? query.page[0] : query.page);
  const rawSize = Number(Array.isArray(query.size) ? query.size[0] : query.size);

  const page = Number.isFinite(rawPage) && rawPage >= 1 ? Math.floor(rawPage) : defaultPage;
  const size = Number.isFinite(rawSize) && rawSize >= 1 ? Math.min(Math.floor(rawSize), MAX_PAGE_SIZE) : defaultSize;

  return { page, size };
}
